Here's an example implementation of a Shape class using polymorphism in C++:

```
#include <iostream>
#include <cmath>

using namespace std;

class Shape {
public:
    virtual double area() = 0;
};

class Rectangle : public Shape {
private:
    double width, height;
public:
    Rectangle(double w, double h): width(w), height(h) {}
    double area() {
        return width * height;
    }
};

class Circle : public Shape {
private:
    double radius;
public:
    Circle(double r) : radius(r) {}
    double area() {
        return M_PI * pow(radius, 2);
    }
};

int main() {
    Shape *myShape;
    Rectangle rect(5, 7);
    Circle circle(10);

    myShape = &rect;
    cout << "Area of rectangle: " << myShape->area() << endl;

    myShape = &circle;
    cout << "Area of circle: " << myShape->area() << endl;

    return 0;
}
```

In this implementation, we define a abstract Shape class with a pure virtual function `area()`. We then define two concrete classes, Rectangle and Circle, which inherit from Shape and implement `area()` according to their respective formulas. In `main()`, we create instances of these classes and assign them to a `Shape*` pointer. We can then call the `area()` function through the pointer, which will dynamically dispatch to the correct implementation based on the underlying object type.

